function looksLikeTaskRow(o) {
  return o && typeof o === 'object' && ('task_id' in o || 'title' in o || 'name' in o || 'status' in o);
}

function parseJsonLenient(s) {
  const t = String(s ?? '').trim();
  if (!t) return null;
  let u = t;
  if (u.startsWith('```')) {
    u = u.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/,'').trim();
  }
  try {
    return JSON.parse(u);
  } catch {
    return null;
  }
}

function drillContentArray(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const c = obj.content;
  if (!Array.isArray(c) || c.length === 0) return obj;
  for (let i = c.length - 1; i >= 0; i--) {
    const part = c[i];
    if (part?.type === 'text' && typeof part.text === 'string') {
      const parsed = parseJsonLenient(part.text);
      if (parsed !== null) return parsed;
    }
    if (typeof part?.text === 'string') {
      const parsed = parseJsonLenient(part.text);
      if (parsed !== null) return parsed;
    }
  }
  const last = c[c.length - 1];
  if (last?.type === 'text' && typeof last.text === 'string') return last.text;
  if (typeof last?.text === 'string') return last.text;
  return obj;
}

let payload = $json;

if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
  const keys = Object.keys(payload);
  if (keys.length === 1 && keys[0] === 'output' && payload.output !== undefined) {
    payload = payload.output;
  }
}

if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
  payload = drillContentArray(payload);
}

if (Array.isArray(payload) && payload[0]?.type === 'text' && typeof payload[0]?.text === 'string') {
  payload = payload[0].text;
}

if (typeof payload === 'string') {
  const parsed = parseJsonLenient(payload);
  if (parsed !== null) payload = parsed;
}

if (Array.isArray(payload) && payload.length === 1 && payload[0]?.type === 'text' && typeof payload[0]?.text === 'string') {
  const inner = parseJsonLenient(payload[0].text);
  if (inner !== null) payload = inner;
  else {
    const t = payload[0].text;
    const inner2 = typeof t === 'string' ? parseJsonLenient(t) : null;
    payload = inner2 !== null ? inner2 : {};
  }
}

if (typeof payload === 'object' && payload !== null && !Array.isArray(payload)) {
  for (const k of ['response', 'result', 'text']) {
    const v = payload[k];
    if (typeof v === 'string' && v.trim()) {
      const parsed = parseJsonLenient(v);
      if (parsed !== null) {
        payload = parsed;
        break;
      }
    }
  }
}

if (Array.isArray(payload) && payload.length > 0 && payload.every(looksLikeTaskRow)) {
  payload = { tasks: payload };
}

return { json: { payload } };
